-- Cheap change tokens: unrelated cache access / heartbeat writes do not wake readers.
CREATE TABLE runtime_revision (id INTEGER PRIMARY KEY CHECK(id=1), catalog INTEGER NOT NULL, work INTEGER NOT NULL);
INSERT INTO runtime_revision VALUES(1,0,0);
CREATE INDEX media_readiness ON media_info(asset_id,revision,json_extract(data_json,'$.version'),coalesce(json_extract(data_json,'$.metadata_only'),0),updated);
CREATE INDEX analysis_readiness ON analysis(asset_id,revision,provider,version,json_extract(data_json,'$.input_media_version'),json_extract(data_json,'$.input_preview_updated'));
CREATE TRIGGER runtime_entries_insert AFTER INSERT ON entries BEGIN UPDATE runtime_revision SET catalog=catalog+1,work=work+1 WHERE id=1; END;
CREATE TRIGGER runtime_entries_delete AFTER DELETE ON entries BEGIN UPDATE runtime_revision SET catalog=catalog+1,work=work+1 WHERE id=1; END;
CREATE TRIGGER runtime_entries_update AFTER UPDATE OF revision,missing,scope_excluded,parent,path,event_json,seen_job,kind ON entries WHEN OLD.revision IS NOT NEW.revision OR OLD.missing IS NOT NEW.missing OR OLD.scope_excluded IS NOT NEW.scope_excluded OR OLD.parent IS NOT NEW.parent OR OLD.path IS NOT NEW.path OR OLD.event_json IS NOT NEW.event_json OR OLD.seen_job IS NOT NEW.seen_job OR OLD.kind IS NOT NEW.kind BEGIN UPDATE runtime_revision SET catalog=catalog+1,work=work+1 WHERE id=1; END;
CREATE TRIGGER runtime_media_info_insert AFTER INSERT ON media_info BEGIN UPDATE runtime_revision SET catalog=catalog+1,work=work+1 WHERE id=1; END;
CREATE TRIGGER runtime_media_info_delete AFTER DELETE ON media_info BEGIN UPDATE runtime_revision SET catalog=catalog+1,work=work+1 WHERE id=1; END;
CREATE TRIGGER runtime_media_info_update AFTER UPDATE OF revision,data_json,updated ON media_info WHEN OLD.revision IS NOT NEW.revision OR OLD.data_json IS NOT NEW.data_json OR OLD.updated IS NOT NEW.updated BEGIN UPDATE runtime_revision SET catalog=catalog+1,work=work+1 WHERE id=1; END;
CREATE TRIGGER runtime_analysis_insert AFTER INSERT ON analysis BEGIN UPDATE runtime_revision SET catalog=catalog+1,work=work+1 WHERE id=1; END;
CREATE TRIGGER runtime_analysis_delete AFTER DELETE ON analysis BEGIN UPDATE runtime_revision SET catalog=catalog+1,work=work+1 WHERE id=1; END;
CREATE TRIGGER runtime_analysis_update AFTER UPDATE OF revision,provider,version,data_json,updated ON analysis WHEN OLD.revision IS NOT NEW.revision OR OLD.provider IS NOT NEW.provider OR OLD.version IS NOT NEW.version OR OLD.data_json IS NOT NEW.data_json OR OLD.updated IS NOT NEW.updated BEGIN UPDATE runtime_revision SET catalog=catalog+1,work=work+1 WHERE id=1; END;
CREATE TRIGGER runtime_metadata_insert AFTER INSERT ON metadata BEGIN UPDATE runtime_revision SET catalog=catalog+1,work=work+1 WHERE id=1; END;
CREATE TRIGGER runtime_metadata_delete AFTER DELETE ON metadata BEGIN UPDATE runtime_revision SET catalog=catalog+1,work=work+1 WHERE id=1; END;
CREATE TRIGGER runtime_metadata_update AFTER UPDATE OF value_json,info_json,stale,source_revision ON metadata WHEN OLD.value_json IS NOT NEW.value_json OR OLD.info_json IS NOT NEW.info_json OR OLD.stale IS NOT NEW.stale OR OLD.source_revision IS NOT NEW.source_revision BEGIN UPDATE runtime_revision SET catalog=catalog+1,work=work+1 WHERE id=1; END;
CREATE TRIGGER runtime_curation_insert AFTER INSERT ON curation BEGIN UPDATE runtime_revision SET catalog=catalog+1 WHERE id=1; END;
CREATE TRIGGER runtime_curation_delete AFTER DELETE ON curation BEGIN UPDATE runtime_revision SET catalog=catalog+1 WHERE id=1; END;
CREATE TRIGGER runtime_curation_update AFTER UPDATE OF pinned,excluded ON curation WHEN OLD.pinned IS NOT NEW.pinned OR OLD.excluded IS NOT NEW.excluded BEGIN UPDATE runtime_revision SET catalog=catalog+1 WHERE id=1; END;
CREATE TRIGGER runtime_derivatives_insert AFTER INSERT ON derivatives BEGIN UPDATE runtime_revision SET catalog=catalog+1 WHERE id=1; END;
CREATE TRIGGER runtime_derivatives_delete AFTER DELETE ON derivatives BEGIN UPDATE runtime_revision SET catalog=catalog+1 WHERE id=1; END;
CREATE TRIGGER runtime_derivatives_update AFTER UPDATE OF status,path,revision ON derivatives WHEN OLD.status IS NOT NEW.status OR OLD.path IS NOT NEW.path OR OLD.revision IS NOT NEW.revision BEGIN UPDATE runtime_revision SET catalog=catalog+1 WHERE id=1; END;
CREATE TRIGGER runtime_sources_insert AFTER INSERT ON sources BEGIN UPDATE runtime_revision SET catalog=catalog+1,work=work+1 WHERE id=1; END;
CREATE TRIGGER runtime_sources_delete AFTER DELETE ON sources BEGIN UPDATE runtime_revision SET catalog=catalog+1,work=work+1 WHERE id=1; END;
CREATE TRIGGER runtime_sources_update AFTER UPDATE OF root ON sources WHEN OLD.root IS NOT NEW.root BEGIN UPDATE runtime_revision SET catalog=catalog+1,work=work+1 WHERE id=1; END;
CREATE TRIGGER runtime_settings_insert AFTER INSERT ON settings BEGIN UPDATE runtime_revision SET catalog=catalog+1,work=work+1 WHERE id=1; END;
CREATE TRIGGER runtime_settings_delete AFTER DELETE ON settings BEGIN UPDATE runtime_revision SET catalog=catalog+1,work=work+1 WHERE id=1; END;
CREATE TRIGGER runtime_settings_update AFTER UPDATE OF value ON settings WHEN OLD.value IS NOT NEW.value BEGIN UPDATE runtime_revision SET catalog=catalog+1,work=work+1 WHERE id=1; END;
CREATE TRIGGER runtime_media_jobs_insert AFTER INSERT ON media_jobs BEGIN UPDATE runtime_revision SET work=work+1 WHERE id=1; END;
CREATE TRIGGER runtime_media_jobs_delete AFTER DELETE ON media_jobs BEGIN UPDATE runtime_revision SET work=work+1 WHERE id=1; END;
CREATE TRIGGER runtime_media_jobs_update AFTER UPDATE OF status,available,lease_until,revision ON media_jobs WHEN OLD.status IS NOT NEW.status OR OLD.available IS NOT NEW.available OR OLD.lease_until IS NOT NEW.lease_until OR OLD.revision IS NOT NEW.revision BEGIN UPDATE runtime_revision SET work=work+1 WHERE id=1; END;
CREATE TRIGGER runtime_jobs_insert AFTER INSERT ON jobs BEGIN UPDATE runtime_revision SET work=work+1 WHERE id=1; END;
CREATE TRIGGER runtime_jobs_delete AFTER DELETE ON jobs BEGIN UPDATE runtime_revision SET work=work+1 WHERE id=1; END;
CREATE TRIGGER runtime_jobs_update AFTER UPDATE OF status ON jobs WHEN OLD.status IS NOT NEW.status BEGIN UPDATE runtime_revision SET work=work+1 WHERE id=1; END;
